from pathlib import Path
p=Path('excel-export.js');s=p.read_text(encoding='utf8');style=s.split("'xl/styles.xml':`",1)[1].split('`',1)[0]
fn=r'''
function reportWorkbook(sections,{rtl=true}={}){
 const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main',rels='http://schemas.openxmlformats.org/package/2006/relationships',used=new Set(),names=[];
 if(!sections.length)throw Error('لا توجد أقسام للتصدير');
 const files={},sheetDefs=[],links=[],types=[];
 const cell=(value,r,c,style=0)=>typeof value==='number'&&Number.isFinite(value)?`<c r="${column(c)}${r}" s="${style}"><v>${value}</v></c>`:`<c r="${column(c)}${r}" s="${style}" t="inlineStr"><is><t xml:space="preserve">${escape(value)}</t></is></c>`;
 sections.forEach((section,index)=>{
  const base=String(section.name||'Sheet').replace(/[\\/?*\[\]:]/g,' ').replace(/^'+|'+$/g,'').trim().slice(0,31)||'Sheet';let name=base,n=1;while(used.has(name.toLowerCase())){const suffix=' ('+(++n)+')';name=base.slice(0,31-suffix.length)+suffix}used.add(name.toLowerCase());names.push(name);
  const headers=section.headers,rows=section.rows;if(!headers.length)throw Error('أعمدة التقرير غير موجودة');const last=column(headers.length-1),lastRow=rows.length+3;
  files[`xl/worksheets/sheet${index+1}.xml`]=`<worksheet xmlns="${ns}"><sheetViews><sheetView workbookViewId="0" rightToLeft="${rtl?1:0}"><pane ySplit="3" topLeftCell="A4" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>${headers.map((h,i)=>`<col min="${i+1}" max="${i+1}" width="${i===0?28:24}" customWidth="1"/>`).join('')}</cols><sheetData><row r="1" ht="30" customHeight="1">${cell(section.name,1,0,1)}</row><row r="2" ht="44" customHeight="1">${cell(section.note||'',2,0)}</row><row r="3" ht="28" customHeight="1">${headers.map((h,i)=>cell(h,3,i,1)).join('')}</row>${rows.map((row,r)=>`<row r="${r+4}" ht="28" customHeight="1">${headers.map((h,c)=>cell(row[c],r+4,c)).join('')}</row>`).join('')}</sheetData><autoFilter ref="A3:${last}${Math.max(3,lastRow)}"/>${headers.length>1?`<mergeCells count="2"><mergeCell ref="A1:${last}1"/><mergeCell ref="A2:${last}2"/></mergeCells>`:''}<pageMargins left="0.3" right="0.3" top="0.5" bottom="0.5" header="0.2" footer="0.2"/></worksheet>`;
  sheetDefs.push(`<sheet name="${escape(name)}" sheetId="${index+1}" r:id="rId${index+1}"/>`);links.push(`<Relationship Id="rId${index+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${index+1}.xml"/>`);types.push(`<Override PartName="/xl/worksheets/sheet${index+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`);
 });
 files['[Content_Types].xml']=`<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${types.join('')}</Types>`;
 files['_rels/.rels']=`<Relationships xmlns="${rels}"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`;
 files['xl/workbook.xml']=`<workbook xmlns="${ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheetDefs.join('')}</sheets></workbook>`;
 files['xl/_rels/workbook.xml.rels']=`<Relationships xmlns="${rels}">${links.join('')}<Relationship Id="rId${sections.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`;
 files['xl/styles.xml']=`STYLE_XML`;
 return zip(files);
}
'''.replace('STYLE_XML',style.replace('xfId="0"/>','xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf>'))
s=s.replace('root.MasalExcel={workbook};',fn+'\nroot.MasalExcel={workbook,reportWorkbook};');p.write_text(s,encoding='utf8')
p=Path('enhancements.js');s=p.read_text(encoding='utf8');old="download('masal-report-'+Masal.day()+'.html',this.reportDocument(),'text/html;charset=utf-8');";new="""const sections=this.reportExportSections(true);const sheets=[{name:this.tr('تقرير النظام الشامل'),note:this.tr('الفلاتر الزمنية تخص الحركات؛ المخزون والشبكة والإعدادات تعرض الوضع الحالي. لا يتضمن التقرير رموز البطاقات.'),headers:[this.tr('الحقل'),this.tr('القيمة')],rows:this.reportMetadata().map(m=>[this.tr(m.label),m.value])},...sections.map(s=>({name:this.tr(s.title),note:this.tr(s.note||'')+' • '+s.rows.length+' '+this.tr('سجل'),headers:s.columns.map(c=>this.tr(c.label)),rows:s.rows.map(r=>s.columns.map(c=>typeof r[c.key]==='number'&&Number.isFinite(r[c.key])?r[c.key]:this.reportCell(r[c.key],c)))}))];download('masal-report-'+Masal.day()+'.xlsx',MasalExcel.reportWorkbook(sheets,{rtl:this.lang!=='en'}),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');this.notify('تم تنزيل التقرير بصيغة Excel');""";assert old in s;s=s.replace(old,new,1);p.write_text(s,encoding='utf8')
p=Path('index.html');s=p.read_text(encoding='utf8').replace("{{tr('تنزيل التقرير المنسق')}}","{{tr('تنزيل التقرير المنسق')}} · Excel",1);p.write_text(s,encoding='utf8')
